
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mcam_b3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mcam_b3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.536824062349202e+00, -3.470313641805579e+00, -3.377168386935578e+00, -3.248246317849528e+00, -3.072793851061294e+00, -2.839725122487502e+00, -2.540607919547511e+00, -2.174898397380558e+00, -1.756347231204721e+00, -1.313779556688963e+00, -8.752250748615885e-01, -5.779176725490927e-01, -4.943363509031828e-01, -4.075274471248077e-01, -2.894721188881314e-01, -1.738003475149671e-01, -9.696941167819401e-02, -6.174432664048572e-02, -3.832275982518771e-02, -2.592872950851810e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


